import { cvConfig } from "@/content/cv.config";
import { links } from "@/content/links.config";
import { getProject, type Project } from "@/content/projects.config";
import type { Locale } from "@/content/types";
import type { Dictionary } from "@/lib/dictionary";
import { availabilityLine } from "@/lib/i18n";

export type CvProps = { t: Dictionary; locale: Locale };

/** The year in the header – the PDFs are regenerated by hand, so it is the year of `npm run cv`. */
export const cvYear = new Date().getFullYear();

/** "https://github.com/adccz/" → "github.com/adccz" – links stay readable on paper. */
export function bare(url: string): string {
  return url.replace(/^https?:\/\//, "").replace(/\/$/, "");
}

/** Contact cells of both CVs – the phone number appears only here, never on the website. */
export function contacts(t: Dictionary): { label: string; href: string; value: string }[] {
  return [
    { label: t.cv.contact.email, href: `mailto:${links.email}`, value: links.email },
    { label: t.cv.contact.phone, href: `tel:${links.phone.replace(/\s/g, "")}`, value: links.phone },
    { label: t.cv.contact.github, href: links.github, value: links.githubLabel },
    ...(links.linkedin ? [{ label: t.contact.linkedin, href: links.linkedin, value: bare(links.linkedin) }] : []),
    { label: t.cv.contact.web, href: links.site, value: links.siteLabel },
  ];
}

/** "20 h/week · Pilsen or remote" */
export function availability({ t, locale }: CvProps): string {
  return availabilityLine(links.availability.hoursPerWeek, t.availability.hoursUnit, links.availability.location[locale]);
}

export type ProjectLink = { href: string; label: string } | { note: string };

/** Where a project points in the CV: the live demo, else the repository, else the private-repo note. */
export function projectLink(project: Project, { t, locale }: CvProps): ProjectLink {
  const href = project.demo ?? (project.repo ? `https://github.com/${project.repo}` : null);
  if (href) return { href, label: bare(href) };
  return { note: project.privateNote?.[locale] ?? t.projects.privateOwn };
}

/** Czech typography: a one-letter preposition or conjunction (v, k, s, z, a, i, o, u) never ends a line. */
export function nbsp(text: string, locale: Locale): string {
  return locale === "cs" ? text.replace(/(?<=^|[\s(„])([AIKOSUVZaikosuvz]) +/g, "$1\u00a0") : text;
}

/** The dictionary with nbsp() applied to every string – the print pages read it instead of the raw one. */
export function typeset<T>(value: T, locale: Locale): T {
  if (typeof value === "string") return nbsp(value, locale) as T;
  if (Array.isArray(value)) return value.map((item: unknown) => typeset(item, locale)) as T;
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, typeset(item, locale)])) as T;
  }
  return value;
}

/** The one-sentence summary, or the full description where a project has none. */
export function projectSummary(project: Project, locale: Locale): string {
  return nbsp((project.summary ?? project.description)[locale], locale);
}

/** Projects of the design CV's grid, in the configured order. */
export const cvProjects: Project[] = cvConfig.projects.flatMap((id) => getProject(id) ?? []);
